import{_ as e,o as l,c as t,O as i}from"./chunks/framework.ccd0435f.js";const o="/pms-doc/assets/cg-zlfk.d1f6b05f.png",p=JSON.parse('{"title":"质量反馈","description":"","frontmatter":{},"headers":[],"relativePath":"采购管理/质量反馈.md","filePath":"采购管理/质量反馈.md"}'),r={name:"采购管理/质量反馈.md"};function s(n,a,c,d,h,u){return l(),t("div",null,a[0]||(a[0]=[i('<h1 id="质量反馈" tabindex="-1">质量反馈 <a class="header-anchor" href="#质量反馈" aria-label="Permalink to &quot;质量反馈&quot;">​</a></h1><blockquote><p>&quot;质量反馈列表”位于&quot;采购管理板块，采购方在收到货物后送去入厂检检验,检验时不合格的产品选择了，不合格退，整批退，需审批（不合格退，整批退）时，质量反馈列表中将记录不合格的信息</p><p>反馈：如果对方用了咱们的系统，则显示反馈</p><p>完结：如果对方未使用咱们的系统，则显示完结</p></blockquote><h4 id="_1-反馈" tabindex="-1">1.反馈 <a class="header-anchor" href="#_1-反馈" aria-label="Permalink to &quot;1.反馈&quot;">​</a></h4><ul><li>点击反馈按钮输入反馈需求</li><li>对方将在销售管理的售后服务列表中看到您的反馈信息，并处理</li></ul><h4 id="_2-完结" tabindex="-1">2.完结 <a class="header-anchor" href="#_2-完结" aria-label="Permalink to &quot;2.完结&quot;">​</a></h4><ul><li>点击完结按钮输入处理结果，处理时间，可完结这个不合格产品的信息</li><li>如果对方用了咱们的系统，则显示反馈，如果对方未使用咱们的系统，则显示完结</li></ul><h4 id="_3-采购员" tabindex="-1">3.采购员 <a class="header-anchor" href="#_3-采购员" aria-label="Permalink to &quot;3.采购员&quot;">​</a></h4><ul><li>鼠标悬浮在采购员名称上面显示采购员的基础信息（姓名，电话，部门）</li></ul><h4 id="_4-反馈详情" tabindex="-1">4.反馈详情 <a class="header-anchor" href="#_4-反馈详情" aria-label="Permalink to &quot;4.反馈详情&quot;">​</a></h4><ul><li>点击查看详情，可查看这个不合格品的，编号，名称，型号规格，收货量，检验量，反馈量，单位，检验结论，创建时间，需求，处理结果（需对方处理完可看到处理结果）</li><li>点击反馈量对应的数字可查看合格率，检验员，质检详情，质检报告，不合格概述，检验日期</li><li>质检详情：可查看质检的检验项，检验方法，检验要求，使用设备，检验结果，备注信息</li><li>质检报告：检验时所上传的报告，点击可查看</li></ul><p><img src="'+o+'" alt="如图所示"></p>',11)]))}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
